# Dump of table new_tracks
# ------------------------------------------------------------

DROP TABLE IF EXISTS `new_tracks`;

CREATE TABLE `new_tracks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `track` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_url` text COLLATE utf8mb4_unicode_ci,
  `playlist_id` int(10) unsigned DEFAULT NULL,
  `release_year` smallint(5) unsigned DEFAULT NULL,
  `energy` decimal(4,3) DEFAULT NULL,
  `copy_title_count` int(10) unsigned NOT NULL DEFAULT '0',
  `image_url` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_new_tracks_track` (`track`(191)),
  KEY `fk_new_tracks_playlist` (`playlist_id`),
  CONSTRAINT `fk_new_tracks_playlist` FOREIGN KEY (`playlist_id`) REFERENCES `playlist` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `new_tracks` WRITE;
/*!40000 ALTER TABLE `new_tracks` DISABLE KEYS */;

